(()=>{const root=document.querySelector(".auth-referral-offer .rewards");if(!root)return;const cards=[...root.querySelectorAll(".dealer")],pulses=[...root.querySelectorAll(".pulse")],amount=root.querySelector("#amount"),discount=root.querySelector("#discount"),label=root.querySelector("#label"),counter=root.querySelector(".counter");const reduced=matchMedia("(prefers-reduced-motion:reduce)");let started=0,elapsed=0,frame=0,last=-1;function stage(n){cards.forEach((c,i)=>c.classList.toggle("active",i<n));amount.textContent=100-n*25;discount.textContent=n*25+"% off";label.textContent="With "+n+" active qualifying referral"+(n===1?"":"s");counter.classList.remove("bump");void counter.offsetWidth;if(n)counter.classList.add("bump")}function tick(t){if(document.hidden)return;elapsed=t-started;const n=Math.min(4,Math.max(0,Math.floor((elapsed-2450)/1700)));if(n!==last){stage(n);last=n}pulses.forEach((p,i)=>{const start=2450+(i+1)*1700-600;if(elapsed>=start)cards[i].classList.add("active");p.classList.toggle("fire",elapsed>=start&&elapsed<start+650)});if(elapsed<9800)frame=requestAnimationFrame(tick)}function play(){cancelAnimationFrame(frame);pulses.forEach(p=>p.classList.remove("fire"));last=-1;elapsed=0;stage(0);if(reduced.matches){stage(4);return}started=performance.now();frame=requestAnimationFrame(tick)}document.addEventListener("visibilitychange",()=>{cancelAnimationFrame(frame);if(hasStarted&&!document.hidden&&elapsed<9800&&!reduced.matches){started=performance.now()-elapsed;frame=requestAnimationFrame(tick)}});let hasStarted=false;const watcher=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&!hasStarted){hasStarted=true;play();watcher.disconnect()}},{threshold:.4});watcher.observe(root)})();